package main

// ADR-0055 V5 on the real tree (stage S2b-2). Unlike main_test.go, this file reads the
// repository's own scenarios/ and challenges/, so `go test ./...` (the required `test` job,
// make test) runs `gen-scenarios --check` on what is committed:
//   - there is at least one source, and each committed scenario.yaml is byte for byte what
//     its source generates (a directory with no source is generate's error, main_test.go);
//   - the check is not vacuous: one byte changed in what is compared is red;
//   - each generated file is in the form the shell readers of `challenges:` agree on, and
//     catalog.LoadScenario reads the same id and list from it;
//   - the migration golden: the three scenarios that existed before the migration keep the
//     title and the scope catalog.LoadScored read from their hand-written scenario.yaml
//     (main 88159c3).

import (
	"bytes"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/Qfour/falco-ctf-app/internal/catalog"
	"github.com/Qfour/falco-ctf-app/internal/edition"
)

// realRoot is the repository root, from this package's directory.
const realRoot = "../.."

func TestRealTree_ScenarioYAMLIsGenerated(t *testing.T) {
	files, err := generate(realRoot)
	if err != nil {
		t.Fatalf("generate %s: %v", realRoot, err)
	}
	if len(files) == 0 {
		t.Fatal("no module.yaml or course.yaml under scenarios/: the root is wrong or the tree moved")
	}
	var stdout, stderr bytes.Buffer
	if code := run([]string{"--check", realRoot}, &stdout, &stderr); code != exitOK {
		t.Fatalf("gen-scenarios --check: exit %d\n%s\nedit the module.yaml / course.yaml, run make gen-scenarios and commit the result", code, stderr.String())
	}
	for _, f := range files {
		id := strings.Split(f.rel, "/")[1]
		ids, err := readerShape(string(f.data))
		if err != nil {
			t.Errorf("%s: not in the shell readers' form: %v", f.rel, err)
			continue
		}
		s, err := catalog.LoadScenario(filepath.Join(realRoot, filepath.FromSlash(f.rel)))
		if err != nil || s.ID != id || !slices.Equal(s.Challenges, ids) {
			t.Errorf("%s: LoadScenario = %+v, %v; want id %q and the shell readers' %v", f.rel, s, err, id, ids)
		}
	}
}

// The comparison of --check is with the committed files: the generated bytes with one byte
// appended differ from each of them, and the stale file is named.
func TestRealTree_CheckIsRedOnAOneByteDifference(t *testing.T) {
	files, err := generate(realRoot)
	if err != nil || len(files) == 0 {
		t.Fatalf("generate %s: %d files, %v", realRoot, len(files), err)
	}
	for i := range files {
		edited := slices.Clone(files)
		edited[i].data = append(slices.Clone(edited[i].data), ' ')
		var stdout, stderr bytes.Buffer
		code := checkFiles(realRoot, edited, &stdout, &stderr)
		if code != exitStale || !strings.Contains(stderr.String(), files[i].rel+" differs") {
			t.Errorf("%s with one byte appended: exit %d, stderr %q; want %d naming it", files[i].rel, code, stderr.String(), exitStale)
		}
	}
}

// migrationGolden is each scenario that existed before the migration, as catalog.LoadScored
// read it from its hand-written scenario.yaml on main 88159c3: its id, its title (the value
// of `title:` there, unquoted), its order (Order), and the digest of that order
// (edition.ScopeDigest, ADR-0056 B12). The digests were computed
// outside this code, as testdata/scope-digest/cases.tsv's are: the sha256 (openssl dgst
// -sha256) of the label line and one line per id, each ending with LF. A row is never edited
// to make the test pass: a difference is a change of what the participants and the platform
// see, and is reviewed as one.
var migrationGolden = []struct {
	id, title string
	order     []string
	digest    string
}{
	{
		id:    "nimbusbreach-full",
		title: "CTF Company — Full Scenario (10 missions)",
		order: []string{
			"01-initial-recon", "02-credential-files", "03-stealth-read", "04-key-search", "05-silent-search",
			"06-web-rce-shell", "07-persist", "08-c2-beacon", "09-hidden-cache", "10-final-exfil",
		},
		digest: "c3090f5c04a3a555a7b7ae127a14628df81f8d549b167c4f2e70e32294ff6e7a",
	},
	{
		id:    "nimbusbreach-with-tutorial",
		title: "CTF Company — Full Scenario + Tutorial (11 missions)",
		order: []string{
			"00-tutorial",
			"01-initial-recon", "02-credential-files", "03-stealth-read", "04-key-search", "05-silent-search",
			"06-web-rce-shell", "07-persist", "08-c2-beacon", "09-hidden-cache", "10-final-exfil",
		},
		digest: "498a254d85035b67fcad6c5b3280e5af7598ea8c9bda6a36a380b7def0359184",
	},
	{
		id:     "tutorial-intro",
		title:  "遊び方チュートリアル — 導入コース (0問目 + 例題)",
		order:  []string{"00-tutorial", "01-initial-recon", "03-stealth-read"},
		digest: "b330f742e89f03c73c1eeca2f0a222dd433b95c1d5329d57766ed5373c2edc6a",
	},
}

func TestRealTree_MigrationKeepsEachScope(t *testing.T) {
	challenges := filepath.Join(realRoot, "challenges")
	for _, g := range migrationGolden {
		t.Run(g.id, func(t *testing.T) {
			if d := edition.ScopeDigest(g.order); d != g.digest {
				t.Fatalf("the golden row is inconsistent: ScopeDigest(order) = %s, pinned %s", d, g.digest)
			}
			file := filepath.Join(realRoot, filepath.FromSlash(path.Join("scenarios", g.id, "scenario.yaml")))
			scored, err := catalog.LoadScored(challenges, file, "")
			if err != nil {
				t.Fatalf("LoadScored(%s): %v", file, err)
			}
			if scored.ScenarioID != g.id {
				t.Errorf("ScenarioID = %q, want %q", scored.ScenarioID, g.id)
			}
			if s, err := catalog.LoadScenario(file); err != nil || s.Title != g.title {
				t.Errorf("LoadScenario(%s): title %q, %v; want the title before the migration %q", file, s.Title, err, g.title)
			}
			if !slices.Equal(scored.Order, g.order) {
				t.Errorf("Order = %v\nwant the order before the migration %v", scored.Order, g.order)
			}
			if len(scored.Catalog) != len(g.order) {
				t.Errorf("the scored catalog holds %d challenges, want %d", len(scored.Catalog), len(g.order))
			}
			if d := edition.ScopeDigest(scored.Order); d != g.digest {
				t.Errorf("ScopeDigest(Order) = %s, want the digest before the migration %s", d, g.digest)
			}
		})
	}
}
